#!/bin/bash
# Uninstall script for Chipmunk Log Analyzer & Viewer
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling Chipmunk Log Analyzer & Viewer..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping Chipmunk Log Analyzer & Viewer if running..."
pkill -f "Chipmunk Log Analyzer & Viewer" 2>/dev/null || true

# Remove /Applications/chipmunk.app
echo "Removing /Applications/chipmunk.app..."
if [ -d "/Applications/chipmunk.app" ]; then
    rm -rf "/Applications/chipmunk.app" 2>/dev/null || true
elif [ -f "/Applications/chipmunk.app" ]; then
    rm -f "/Applications/chipmunk.app" 2>/dev/null || true
fi

# Remove $HOME/.chipmunk
echo "Removing $HOME/.chipmunk..."
if [ -d "$HOME/.chipmunk" ]; then
    rm -rf "$HOME/.chipmunk" 2>/dev/null || true
elif [ -f "$HOME/.chipmunk" ]; then
    rm -f "$HOME/.chipmunk" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/Chipmunk
echo "Removing $HOME/Library/Application Support/Chipmunk..."
if [ -d "$HOME/Library/Application Support/Chipmunk" ]; then
    rm -rf "$HOME/Library/Application Support/Chipmunk" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Support/Chipmunk" ]; then
    rm -f "$HOME/Library/Application Support/Chipmunk" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
